nta.declaration:
// rsk UPPAAL export (rsk-uppaal/4). Times in CPU cycles.
const int N = 5;
typedef int[0,N-1] task_t;
const int PRIO[N] = { 7, 6, 5, 4, 2 };
const int PERIOD[N] = { 1280000, 3200000, 3200000, 1280000, 3200000 };
const int DEADLINE[N] = { 128000, 192000, 256000, 1280000, 3200000 };
const int EXEC[N] = { 99820, 99749, 100508, 410202, 189535 };
const int OWN[N] = { 71045, 71045, 71045, 371651, 173440 };
const int JITTER[N] = { 7543, 7543, 7543, 7543, 7543 };
const int BLOCK[N] = { 25780, 25780, 25780, 8714, 8714 };
const bool SPORADIC[N] = { true, true, true, false, false };
// Task_Model identifiers, by index (R31.7):
// 0: therapy.pace
// 1: therapy.sense_v
// 2: therapy.sense_a
// 3: therapy.control
// 4: comms.link
int ceiling = 0;          // System_Ceiling (SRP); Critical_Sections are approximated by BLOCK
int running = -1;         // the executing Task, -1 when idle
bool pending[N];          // released, not started
bool started[N];          // started and not completed (executing or preempted)
chan release[N];
urgent broadcast chan go;  // dispatch: no time passes while a Task is eligible
clock dl[N];              // time since the nominal release instant
clock exec[N];            // stopwatches: progress only while running (a rate of 0 or 1 in the invariant; `hybrid clock` is for the statistical checker and crashes verifyta's symbolic one)
bool preempts(task_t i, int j) { return j < 0 || PRIO[i] > PRIO[j] || (PRIO[i] == PRIO[j] && i < j); }
bool eligible(task_t i) { return pending[i] && PRIO[i] > ceiling && preempts(i, running); }
// The Task that resumes when the executing one completes: the started one of highest Priority, lowest identifier among equals (R7.3); -1 when none.
int resume() { int best = -1; for (k : task_t) { if (started[k] && (best < 0 || PRIO[k] > PRIO[best])) { best = k; } } return best; }

nta.system:
G0 = Gen(0); T0 = Task(0);
G1 = Gen(1); T1 = Task(1);
G2 = Gen(2); T2 = Task(2);
G3 = Gen(3); T3 = Task(3);
G4 = Gen(4); T4 = Task(4);
system G0, T0, G1, T1, G2, T2, G3, T3, G4, T4;
